def squash(s: str) -> str:
    n = len(s)
    out: list[str] = []
    i = 0
    while i < n:
        ch = s[i]
        j = i + 1
        while j < n and s[j] == ch:
            j += 1
        count = j - i
        esc = "\\" + ch if ("0" <= ch <= "9" or ch == "\\") else ch
        if count >= 3:
            out.append(f"{count}{esc}")
        else:
            out.append(esc * count)
        i = j
    return "".join(out)
